import sys; sys.path.insert(0,'/tmp')
import ana2,numpy as np,json,pickle
ecgs=json.load(open('ecgs.json'))
out={}
for i,e in enumerate(ecgs):
    try:
        r=ana2.analyze(e['ecg'])
    except Exception as ex:
        r={'err':str(ex)}
    m=r.pop('meas',None); M=r.pop('M',None); r.pop('sig',None); pk=r.pop('pk',None); rp=r.pop('r',None)
    if m is not None:
        Mf=m['Mf']; qon=m['qon']; qoff=m['qoff']
        # terminal 40 ms of QRS
        t=slice(max(qon,qoff-int(0.04*ana2.FS)),qoff)
        r['term']={ana2.LEADS[j]:float(Mf[t,j].mean()) for j in range(12)}
        r['qrsnet']={ana2.LEADS[j]:float(Mf[qon:qoff,j].sum()*2/1000) for j in range(12)}
        r['rpeak_amp']={ana2.LEADS[j]:float(Mf[qon:qoff,j].max()) for j in range(12)}
        r['snet']={ana2.LEADS[j]:float(Mf[qon:qoff,j].min()) for j in range(12)}
        r['medbeat']=Mf.tolist()
        r['qon_i']=int(qon); r['qoff_i']=int(qoff); r['toff_i']=int(m['toff']) if m['toff'] else None
        r['pon_i']=int(m['pon']) if m['pon'] is not None else None
        r['ppk_i']=int(m['ppk']) if m['ppk'] is not None else None
        r['rp']=int(rp)
    out[e['ecg']]=r
    if i%20==0: print(i,flush=True)
pickle.dump(out,open('ecgres.pkl','wb'))
print('done')
EOF
