        try:
            _,info=nk.ecg_peaks(x,sampling_rate=500)
            rp=info['ECG_R_Peaks']
            _,d=nk.ecg_delineate(x,rpeaks=rp,sampling_rate=500,method='dwt')
            def md(a,b):
                v=[]
                for i in range(min(len(d[a]),len(d[b]))):
                    if not (np.isnan(d[a][i]) or np.isnan(d[b][i])): v.append(d[b][i]-d[a][i])
                return np.median(v)*2 if v else None
            print(eid,lead,'n',len(rp),'PR',md('ECG_P_Onsets','ECG_R_Onsets'),'QRS',md('ECG_R_Onsets','ECG_R_Offsets'),'QT',md('ECG_R_Onsets','ECG_T_Offsets'))
        except Exception as ex: print(eid,lead,'err',ex)
