import sys; sys.path.insert(0,'/tmp')
import ana3,numpy as np
def strip(eid,lead='II',t0=0.0,dur=4.0,ds=5,rows=17):
    sig=ana3.bp(ana3.load(eid),0.5,40)
    j=ana3.LEADS.index(lead)
    a=int(t0*500); b=int((t0+dur)*500)
    x=sig[a:b:ds,j]
    mx=max(abs(x).max(),1e-6)
    grid=[[' ']*len(x) for _ in range(rows)]
    for i,v in enumerate(x):
        rr=int(round((1-(v/mx))*(rows-1)/2)); rr=min(rows-1,max(0,rr)); grid[rr][i]='*'
    print('--',eid,lead,'t=%.1f-%.1f scale=%.2fmV  %dms/col'%(t0,t0+dur,mx,ds*2))
    for g in grid: print('  |'+''.join(g))
if __name__=='__main__':
    eid=sys.argv[1]
    for l in sys.argv[2].split(','):
        strip(eid,l,float(sys.argv[3]),float(sys.argv[4]))
