import json,subprocess,sys,pickle,numpy as np
from collections import defaultdict
res=pickle.load(open('ecgres3.pkl','rb'))
ecgs=json.load(open('ecgs.json'))
byp=defaultdict(list)
for e in ecgs: byp[e['patient']].append(e)

# manual decisions: eid -> (rhythm, conduction, pr_override)
RH={}
AF=['105060792','102295353','109287357','103088543','107399137','108912996','101771242','101744645',
    '105375026','108211642','107674864','104330494','109757556','105789995','107841896',
    '109550629','107914094','108184246','109839112','101950824','107036253','100867733']
PACED=['102531404','103417522']
PR_OVR={'105862861':110.0,'103521932':100.0}
COND={'104941853':['LBBB'],'103686933':['LBBB'],'105789995':['RBBB'],'103262474':['RBBB'],
      '106516875':['RBBB'],'102280728':['FIRST_DEGREE_AV_BLOCK']}
def rhythm(eid):
    if eid in AF: return 'AF'
    if eid in PACED: return 'PACED'
    return 'SINUS'
def axis_cat(a):
    if -30<=a<=90: return 'NORMAL'
    if -90<=a<-30: return 'LEFT'
    if 90<a<=180: return 'RIGHT'
    return 'EXTREME'
def qtc(eid):
    q=res[eid].get('qtc')
    return int(round(q)) if q else None
def pr(eid):
    if rhythm(eid) in ('AF','PACED'): return None
    if eid in PR_OVR: return PR_OVR[eid]
    return res[eid].get('pr')

rows=[]
for p,v in byp.items():
    v.sort(key=lambda x:x['time'])
    cur=v[-1]; prv=v[-2] if len(v)>1 else None
    e=cur['ecg']; r=res[e]
    ch=[]
    if prv:
        pe=prv['ecg']
        rc,rp=rhythm(e),rhythm(pe)
        if rc=='AF' and rp!='AF': ch.append('NEW_AF')
        if rp=='AF' and rc!='AF': ch.append('RESOLVED_AF')
        if rc=='ATRIAL_FLUTTER' and rp!='ATRIAL_FLUTTER': ch.append('NEW_ATRIAL_FLUTTER')
        if rp=='ATRIAL_FLUTTER' and rc!='ATRIAL_FLUTTER': ch.append('RESOLVED_ATRIAL_FLUTTER')
        if rc=='PACED' and rp!='PACED': ch.append('NEW_PACED_RHYTHM')
        if rp=='PACED' and rc!='PACED': ch.append('RESOLVED_PACED_RHYTHM')
        bc=set(COND.get(e,[]))&{'RBBB','LBBB'}; bp=set(COND.get(pe,[]))&{'RBBB','LBBB'}
        if bc and not bp: ch.append('NEW_BUNDLE_BRANCH_BLOCK')
        if bp and not bc: ch.append('RESOLVED_BUNDLE_BRANCH_BLOCK')
        qc,qp=qtc(e),qtc(pe)
        if qc and qp:
            if qc-qp>=60: ch.append('QTC_INCREASE_60')
            elif qp-qc>=60: ch.append('QTC_DECREASE_60')
    rows.append(dict(patient=p,ecg=e,time=cur['time'],prior_ecg=prv['ecg'] if prv else None,
        prior_time=prv['time'] if prv else None,
        rhythm=rhythm(e),ventricular_rate=int(round(r['rate'])),pr_ms=pr(e),
        qrs_ms=r['qrs'],qtc_ms=qtc(e),axis=axis_cat(r['axis']),axis_deg=round(r['axis']),
        conduction=COND.get(e,[]),changes=ch,
        prior_rhythm=rhythm(prv['ecg']) if prv else None,prior_qtc=qtc(prv['ecg']) if prv else None))
json.dump(rows,open('interps.json','w'),indent=1)
for x in rows:
    print('%-8s %s %-10s %-6s %3d PR%-6s QRS%-5s QTc%-5s %-7s(%4d) %-28s %s | prior %s %s %s'%(
      x['patient'][:8],x['time'][:10],x['ecg'],x['rhythm'],x['ventricular_rate'],x['pr_ms'],x['qrs_ms'],x['qtc_ms'],
      x['axis'],x['axis_deg'],','.join(x['conduction']) or '-',','.join(x['changes']) or '-',
      x['prior_ecg'],x['prior_rhythm'],x['prior_qtc']))
print(len(rows))
