cd /tmp && cat > push.py <<'PYEOF'
import json,subprocess,sys,pickle
rows=json.load(open('interps.json'))
res=pickle.load(open('ecgres3.pkl','rb'))
CHTXT={'NEW_AF':'new atrial fibrillation compared with the prior tracing',
 'RESOLVED_AF':'atrial fibrillation on the prior tracing has resolved (now sinus)',
 'NEW_PACED_RHYTHM':'new paced rhythm','RESOLVED_PACED_RHYTHM':'paced rhythm resolved',
 'NEW_BUNDLE_BRANCH_BLOCK':'new bundle branch block','RESOLVED_BUNDLE_BRANCH_BLOCK':'bundle branch block on the prior tracing has resolved',
 'QTC_INCREASE_60':'QTc increased by 60 ms or more','QTC_DECREASE_60':'QTc decreased by 60 ms or more',
 'NEW_ATRIAL_FLUTTER':'new atrial flutter','RESOLVED_ATRIAL_FLUTTER':'atrial flutter resolved'}
RHTXT={'SINUS':'sinus rhythm','AF':'atrial fibrillation','PACED':'paced rhythm','ATRIAL_FLUTTER':'atrial flutter','OTHER':'other rhythm'}
for x in rows:
    r=res[x['ecg']]
    parts=[]
    rr=r['rri']
    if x['rhythm']=='AF':
        parts.append('%s at a mean ventricular rate of %d bpm: RR intervals irregularly irregular (median RR %.2f s, range %.2f-%.2f s, RR coefficient of variation %.2f) with no organised or consistent P waves (P-wave amplitude in the averaged beat %.2f mV, beat-to-beat P-wave correlation %.2f), so no measurable PR interval.'%(
            RHTXT[x['rhythm']].capitalize(),x['ventricular_rate'],r['rr'],min(rr),max(rr),r['rr_cv'],r.get('pamp') or 0,r.get('pcons') or 0))
    elif x['rhythm']=='PACED':
        parts.append('Paced rhythm at %d bpm: fixed, machine-regular RR intervals (median %.2f s, coefficient of variation %.3f) with narrow high-frequency pacing spikes preceding each wide QRS complex (high-pass spike-to-baseline ratio %.0f).'%(
            x['ventricular_rate'],r['rr'],r['rr_cv'],r['spike']))
    else:
        parts.append('Sinus rhythm at %d bpm: regular RR intervals (median %.2f s, coefficient of variation %.3f) with a consistent upright P wave before every QRS in lead II (P amplitude %.2f mV, beat-to-beat P correlation %.2f).'%(
            x['ventricular_rate'],r['rr'],r['rr_cv'],r.get('pamp') or 0,r.get('pcons') or 0))
    iv='Intervals from the 12-lead signal-averaged beat: '
    iv+=('PR %d ms, '%int(x['pr_ms'])) if x['pr_ms'] else 'no measurable PR interval, '
    iv+='QRS %d ms, QT %d ms, QTc (Bazett) %d ms. '%(int(x['qrs_ms']),int(round(r['qt'])) if r.get('qt') else 0,x['qtc_ms'] or 0)
    iv+='Frontal QRS axis about %+d degrees = %s.'%(x['axis_deg'],x['axis'])
    parts.append(iv)
    if x['conduction']:
        cd=[]
        for c in x['conduction']:
            if c=='LBBB': cd.append('left bundle branch block (QRS %d ms, broad monophasic R in I/aVL/V6 with deep dominant S in V1-V2)'%int(x['qrs_ms']))
            if c=='RBBB': cd.append('right bundle branch block (QRS %d ms, terminal positive deflection in V1 with terminal S in I/V5-V6)'%int(x['qrs_ms']))
            if c=='FIRST_DEGREE_AV_BLOCK': cd.append('first-degree AV block (PR %d ms, every P conducted)'%int(x['pr_ms']))
        parts.append('Conduction: '+'; '.join(cd)+'.')
    else:
        parts.append('No bundle branch block and PR interval not prolonged, so no conduction abnormality reported.')
    if x['prior_ecg']:
        s='Compared with the previous ECG %s (%s, %s, QTc %s ms): '%(x['prior_ecg'],x['prior_time'][:10],RHTXT[x['prior_rhythm']],x['prior_qtc'])
        s+=('; '.join(CHTXT[c] for c in x['changes'])+'.') if x['changes'] else 'no qualifying change in rhythm, bundle branch block status or QTc (QTc change less than 60 ms).'
        parts.append(s)
    else:
        parts.append('No previous ECG is available for this patient, so no comparison could be made.')
    x['explanation']=' '.join(parts)

for x in rows:
    core={'ecg':x['ecg']}
    r=subprocess.run(['clinic','interpretation','add','--json',json.dumps(core)],capture_output=True,text=True)
    if r.returncode!=0: print('FAIL add',x['ecg'],r.stdout,r.stderr); sys.exit(1)
    iid=json.loads(r.stdout)['id']
    body=dict(rhythm=x['rhythm'],ventricular_rate=x['ventricular_rate'],pr_ms=int(x['pr_ms']) if x['pr_ms'] else None,
        qrs_ms=int(x['qrs_ms']),qtc_ms=x['qtc_ms'],axis=x['axis'],conduction=x['conduction'],
        prior_ecg=x['prior_ecg'],changes=x['changes'],explanation=x['explanation'])
    r2=subprocess.run(['clinic','interpretation','update',iid,'--json',json.dumps(body)],capture_output=True,text=True)
    if r2.returncode!=0: print('FAIL upd',iid,r2.stdout,r2.stderr); sys.exit(1)
    print(iid,x['patient'][:8],x['ecg'],x['rhythm'],'ok')
print('done',len(rows))
